paragraph.math:
$$\begin{array}{l}
  {{d_{1}^{2} + d_{2}^{2} + d_{3}^{2} + d_{4}^{2} + d_{5}^{2}} = \left\lbrack {f\left( x_{1} \right) - y_{1}} \right\rbrack^{2} + \left\lbrack {f\left( x_{2} \right) - y_{2}} \right\rbrack^{2} + \left\lbrack {f\left( x_{3} \right) - y_{3}} \right\rbrack^{2}{+ \left\lbrack {f\left( x_{4} \right) - y_{4}} \right\rbrack^{2} + \left\lbrack {f\left( x_{5} \right) - y_{5}} \right\rbrack^{2}}} \\
  {\phantom{d_{1}^{2} + d_{2}^{2} + d_{3}^{2} + d_{4}^{2} + d_{5}^{2}} = \left( {mx_{1} + b - y_{1}} \right)^{2} + \left( {mx_{2} + b - y_{2}} \right)^{2} + \left( {mx_{3} + b - y_{3}} \right)^{2}{+ \left( {mx_{4} + b - y_{4}} \right)^{2} + \left( {mx_{5} + b - y_{5}} \right)^{2}}}
  \end{array}$$

$$\begin{array}{lcl}
  {f(m,b)} & = & {\left( {mx_{1} + b - y_{1}} \right)^{2} + \left( {mx_{2} + b - y_{2}} \right)^{2} + \left( {mx_{3} + b - y_{3}} \right)^{2}} \\
   & & {+ \left( {mx_{4} + b - y_{4}} \right)^{2} + \left( {mx_{5} + b - y_{5}} \right)^{2}}
  \end{array}$$

$$\begin{array}{rcl}
  \frac{\partial f}{\partial b} & = & {2\left( {mx_{1} + b - y_{1}} \right) + 2\left( {mx_{2} + b - y_{2}} \right) + 2\left( {mx_{3} + b - y_{3}} \right)} \\
   & & {+ 2\left( {mx_{4} + b - y_{4}} \right) + 2\left( {mx_{5} + b - y_{5}} \right)} \\
   & = & {2\left\lbrack {\left( {x_{1} + x_{2} + x_{3} + x_{4} + x_{5}} \right)m + 5b - \left( {y_{1} + y_{2} + y_{3} + y_{4} + y_{5}} \right)} \right\rbrack}
  \end{array}$$
